recs.append(R(7573930,"مسالے دار سنگترے کے منی پین کیکس",
"تہوار کے ذائقوں والے خوشگوار منی پین کیکس۔",
"25","30 گرام",
["2 انڈے، پھینٹے ہوئے","1 کھانے کا چمچ 0% چکنائی والا دہی","1 چائے کا چمچ بادام کا ایکسٹریکٹ","50 ملی لیٹر سکمڈ دودھ","100 گرام پورے گندم کا آٹا","آدھا چائے کا چمچ بیکنگ پاؤڈر","3 چائے کے چمچ دانے دار میٹھا کرنے والا (سویٹنر)","1 چائے کا چمچ ملے جلے مصالحے (mixed spice)","1 چائے کا چمچ دار چینی","3 سنگترے – 1 سنگترے کا رس اور چھلکا + پھانکیں","پیش کرنے کے لیے 2 سنگتروں کا چھلکا","80 گرام خشک ملے جلے پھل","1 کھانے کا چمچ انار کے دانے"],
["انڈا، دہی اور بادام کا ایکسٹریکٹ دودھ میں پھینٹ لیں، پھر آٹا، بیکنگ پاؤڈر، سویٹنر اور مصالحے ایک پیالے میں ڈالیں اور دودھ کا آمیزہ آہستہ آہستہ ملاتے جائیں یہاں تک کہ ہموار بیٹر بن جائے۔","سنگترے کا رس، چھلکا اور خشک پھل ڈال کر اچھی طرح ملائیں۔","ایک بڑے نان اسٹک پین میں تیل ڈالیں۔ آمیزے کے چھوٹے ڈیزرٹ چمچ پین میں ڈال کر 1-2 منٹ تلیں، پھر چمچے سے پلٹ دیں اور دوسری طرف ایک یا دو منٹ مزید پکائیں۔","پین کیکس کا قطر تقریباً 3-4 سینٹی میٹر اور موٹائی صرف 3–4 ملی میٹر ہونی چاہیے۔","پیش کرنے کے لیے پین کیکس کو سروِنگ پلیٹر میں رکھیں اور اوپر سنگترے کی پھانکیں رکھیں، چھلکا اور انار کے دانے بکھیر دیں۔"],
["سنگترے کی پھانکیں صاف ستھری نکالنے کے لیے سنگترے کا اوپر اور نیچے کا حصہ کاٹ دیں اور اسے کٹنگ بورڈ پر رکھیں۔ اوپر سے نیچے کی طرف کاٹتے ہوئے، سنگترے کے اندر کاٹے بغیر تمام چھلکا اور سفید ریشہ ہٹا دیں۔ جب آپ تمام ریشہ احتیاط سے ہٹا لیں تو جھلی سے بچتے ہوئے ایک پھانک کے ساتھ کاٹیں، پھر چھری کو موڑ کر باہر کی طرف کاٹیں۔ اس طرح آپ ہر پھانک کو کڑوے ریشے کے بغیر نکال سکتے ہیں۔","پین کیکس میں ادرک یا جائفل جیسے مختلف مصالحے ڈال کر دیکھیں، یا سنگترے کے چھلکے کی جگہ لیموں کا چھلکا استعمال کریں۔",("پھل/سبزیوں کے حصے","فی سرونگ پھل/سبزیوں کے حصے: 0")],[]))
